/*! TinyPDF stub - minimal subset */
(function(global){
  function TinyPDF(){
    this.lines=[];
  }
  TinyPDF.prototype.text=function(txt,x,y){ this.lines.push({t:String(txt),x:x,y:y}); };
  TinyPDF.prototype.save=function(name){
    // Fallback: open new window with printable plain text
    var w = window.open("", "_blank");
    var html = "<pre style='font:14px monospace;white-space:pre-wrap'>"+
      this.lines.map(l=>`(${l.x},${l.y}) `+l.t).join("\n")+
      "</pre>";
    if(w){ w.document.write(html); w.document.close(); }
  };
  global.jspdf = { jsPDF: TinyPDF };
})(window);